// Filter appointments scheduled exactly 24 hours from now (Africa/Casablanca)
const TARGET_MS = 24 * 60 * 60 * 1000;
const TOLERANCE_MS = 30 * 60 * 1000; // ±30 min window
const now = Date.now();
const portalLink = 'https://sites.google.com/view/portail-temara-mall/accueil';

function toE164MA(raw) {
  if (raw == null || raw === '') return '';
  let phone = String(raw).replace(/[\s\-\(\)\.]/g, '');
  if (!phone) return '';
  if (phone.startsWith('+')) return phone;
  if (phone.startsWith('00')) return '+' + phone.slice(2);
  if (phone.startsWith('212')) return '+' + phone;
  if (phone.startsWith('0')) return '+212' + phone.slice(1);
  return '+212' + phone;
}

const confirmed = $input.all().filter(item => {
  const status = (item.json['Statut du RDV'] ?? '').toString().trim();
  return status === 'Confirmé' || status === 'Confirme' || status === 'Confirmed';
});

const due = confirmed.filter(item => {
  const raw = item.json['Date & Heure du RDV'];
  if (!raw) return false;
  const appt = new Date(raw).getTime();
  if (isNaN(appt)) return false;
  const delta = appt - now;
  return delta >= (TARGET_MS - TOLERANCE_MS) && delta <= (TARGET_MS + TOLERANCE_MS);
});

return due.map(item => ({
  json: {
    Nom: item.json['Patient (Nom Complet)'] ?? 'Patient',
    Phone: toE164MA(item.json['Téléphone (WhatsApp)'] ?? ''),
    Email: item.json['Email Contact'] ?? '',
    DateHeure: item.json['Date & Heure du RDV'],
    Link: portalLink
  }
})).filter(item => item.json.Phone);
